sql-set.sql:
-- 1. User info with manager and profile SELECT U."Id" AS "UserId", U."EmpId", U."EmpType", U."auth_type", U."UserName", U."FirstName", U."LastName", U."Email", U."SecondaryEmail", U."PhoneNumber", U."Extension", U."mobile", U."oid", U."preferred_username", U."display_name", U."given_name", U."family_name", U."Position", U."BusinessUnit", U."ManagerId", M."UserName" AS "ManagerUserName", U."AccessLevel", U."IsActive", U."Designation", U."Department", U."Location", U."Organization", U."CorrelationId", U."AuditableRequestId", U."AuditableRequestName", U."AuditableSourceEventName", U."CreatedBy", U."CreatedDateTime", U."UpdatedBy", U."UpdatedDateTime", U."UpdateReason", U."OwnerId", U."IsDeleted", U."IsApproved", U."ApproverId", U."ApprovedDateTime", U."IsAuthorized", U."AuthorizedById", U."AuthorizedDateTime", U."SysData", U."TenantId", U."SubTenantId" FROM "User" AS U LEFT JOIN "User" AS M ON U."ManagerId" = M."Id" AND (M."IsDeleted" IS NULL OR M."IsDeleted" = FALSE) LEFT JOIN "UserProfile" AS UP ON UP."UserId" = U."Id" WHERE (U."IsDeleted" IS NULL OR U."IsDeleted" = FALSE) AND (U."Id" = @userId OR U."oid" = @userId OR U."UserName" = @userId) ORDER BY U."display_name" ASC;
-- 2. User Roles SELECT UR."Id" AS "UserRoleId", R."Id" AS "Id", R."RoleName", R."RoleValue", R."DisplayName", U."UserName", U."Id" AS "UserId" FROM "UserRole" AS UR JOIN "Role" AS R ON (R."IsDeleted" IS NULL OR R."IsDeleted" = FALSE) AND UR."RoleId" = R."Id" JOIN "User" AS U ON (U."IsDeleted" IS NULL OR U."IsDeleted" = FALSE) AND UR."UserId" = U."Id" WHERE (UR."IsDeleted" IS NULL OR UR."IsDeleted" = FALSE) AND (UR."UserId" = @userId OR U."oid" = @userId OR U."UserName" = @userId OR @userId IS NULL OR @userId = '0') ORDER BY R."RoleName" ASC;
-- 3. User Permissions Granted SELECT P."Id" AS "PermissionId", PG."Id" AS "PermissionGrantedId", P."PermissionValue", P."PermissionDisplayName", U."UserName", U."Id" AS "UserId", P."PermissionSetId", AR."DisplayName" AS "PermissionSetName", P."ModuleId", A."DisplayName" AS "ModuleName", P."ApiName", P."PermissionType", P."IsActive" FROM "PermissionGranted" AS PG JOIN "Permission" AS P ON P."Id" = PG."PermissionId" AND (P."IsDeleted" IS NULL OR P."IsDeleted" = FALSE) JOIN "User" AS U ON (U."IsDeleted" IS NULL OR U."IsDeleted" = FALSE) AND PG."UserId" = U."Id" JOIN "AuthReferenceLookup" AS A ON A."Id" = P."ModuleId" JOIN "AuthReferenceLookup" AS AR ON AR."Id" = P."PermissionSetId" WHERE (PG."IsDeleted" IS NULL OR PG."IsDeleted" = FALSE) AND (PG."UserId" = @userId OR U."oid" = @userId OR U."UserName" = @userId OR @userId IS NULL OR @userId = '0') ORDER BY P."PermissionDisplayName" ASC;
-- 4. User Permissions Denied SELECT P."Id" AS "PermissionId", PD."Id" AS "PermissionDeniedId", P."PermissionValue", P."PermissionDisplayName", U."UserName", U."Id" AS "UserId", P."PermissionSetId", AR."DisplayName" AS "PermissionSetName", P."ModuleId", A."DisplayName" AS "ModuleName", P."ApiName", P."PermissionType", P."IsActive" FROM "PermissionDenied" AS PD JOIN "Permission" AS P ON P."Id" = PD."PermissionId" AND (P."IsDeleted" IS NULL OR P."IsDeleted" = FALSE) JOIN "User" AS U ON (U."IsDeleted" IS NULL OR U."IsDeleted" = FALSE) AND PD."UserId" = U."Id" JOIN "AuthReferenceLookup" AS A ON A."Id" = P."ModuleId" JOIN "AuthReferenceLookup" AS AR ON AR."Id" = P."PermissionSetId" WHERE (PD."IsDeleted" IS NULL OR PD."IsDeleted" = FALSE) AND (PD."UserId" = @userId OR U."oid" = @userId OR U."UserName" = @userId OR @userId IS NULL OR @userId = '0') ORDER BY P."PermissionDisplayName" ASC;

-- 1. User info with manager and profile SELECT U."Id" AS "Id", U."EmpId", U."EmpType", U."UserName", U."FirstName", U."LastName", U."Email", U."SecondaryEmail", U."PhoneNumber", U."Extension", U."mobile", U."oid", U."preferred_username", U."display_name", U."given_name", U."family_name", U."Position", U."BusinessUnit", U."ManagerId", M."UserName" AS "ManagerUserName", U."AccessLevel", U."IsActive", U."Designation", U."Department", U."Location", U."Organization", U."CorrelationId", U."AuditableRequestId", U."AuditableRequestName", U."AuditableSourceEventName", U."CreatedBy", U."CreatedDateTime", U."UpdatedBy", U."UpdatedDateTime", U."UpdateReason", U."OwnerId", U."IsDeleted", U."IsApproved", U."ApproverId", U."ApprovedDateTime", U."IsAuthorized", U."AuthorizedById", U."AuthorizedDateTime", U."SysData", U."TenantId", U."SubTenantId", U."auth_type" FROM "User" AS U LEFT JOIN "User" AS M ON U."ManagerId" = M."Id" AND (M."IsDeleted" IS NULL OR M."IsDeleted" = FALSE) LEFT JOIN "UserProfile" AS UP ON UP."UserId" = U."Id" WHERE (U."IsDeleted" IS NULL OR U."IsDeleted" = FALSE) AND (U."Id" = @userId OR U."oid" = @userId OR U."UserName" = @userId OR @userId IS NULL OR @userId = '0') ORDER BY U."display_name" ASC;
-- 2. User Roles SELECT UR."Id" AS "UserRoleId", R."Id" AS "Id", R."RoleName", R."RoleValue", R."DisplayName", U."UserName", U."Id" AS "UserId" FROM "UserRole" AS UR JOIN "Role" AS R ON (R."IsDeleted" IS NULL OR R."IsDeleted" = FALSE) AND UR."RoleId" = R."Id" JOIN "User" AS U ON (U."IsDeleted" IS NULL OR U."IsDeleted" = FALSE) AND UR."UserId" = U."Id" WHERE (UR."IsDeleted" IS NULL OR UR."IsDeleted" = FALSE) AND (UR."UserId" = @userId OR U."oid" = @userId OR U."UserName" = @userId OR @userId IS NULL OR @userId = '0') ORDER BY R."RoleName" ASC;
-- 3. User Permissions Granted SELECT P."Id" AS "PermissionId", PG."Id" AS "PermissionGrantedId", P."PermissionValue", P."PermissionDisplayName", U."UserName", U."Id" AS "UserId", P."PermissionSetId", AR."DisplayName" AS "PermissionSetName", P."ModuleId", A."DisplayName" AS "ModuleName", P."ApiName", P."PermissionType", P."IsActive" FROM "PermissionGranted" AS PG JOIN "Permission" AS P ON P."Id" = PG."PermissionId" AND (P."IsDeleted" IS NULL OR P."IsDeleted" = FALSE) JOIN "User" AS U ON (U."IsDeleted" IS NULL OR U."IsDeleted" = FALSE) AND PG."UserId" = U."Id" JOIN "AuthReferenceLookup" AS A ON A."Id" = P."ModuleId" JOIN "AuthReferenceLookup" AS AR ON AR."Id" = P."PermissionSetId" WHERE (PG."IsDeleted" IS NULL OR PG."IsDeleted" = FALSE) AND (PG."UserId" = @userId OR U."oid" = @userId OR U."UserName" = @userId OR @userId IS NULL OR @userId = '0') ORDER BY P."PermissionDisplayName" ASC;
-- 4. User Permissions Denied SELECT P."Id" AS "PermissionId", PD."Id" AS "PermissionDeniedId", P."PermissionValue", P."PermissionDisplayName", U."UserName", U."Id" AS "UserId", P."PermissionSetId", AR."DisplayName" AS "PermissionSetName", P."ModuleId", A."DisplayName" AS "ModuleName", P."ApiName", P."PermissionType", P."IsActive" FROM "PermissionDenied" AS PD JOIN "Permission" AS P ON P."Id" = PD."PermissionId" AND (P."IsDeleted" IS NULL OR P."IsDeleted" = FALSE) JOIN "User" AS U ON (U."IsDeleted" IS NULL OR U."IsDeleted" = FALSE) AND PD."UserId" = U."Id" JOIN "AuthReferenceLookup" AS A ON A."Id" = P."ModuleId" JOIN "AuthReferenceLookup" AS AR ON AR."Id" = P."PermissionSetId" WHERE (PD."IsDeleted" IS NULL OR PD."IsDeleted" = FALSE) AND (PD."UserId" = @userId OR U."oid" = @userId OR U."UserName" = @userId OR @userId IS NULL OR @userId = '0') ORDER BY P."PermissionDisplayName" ASC;
-- 5. User UI Permissions (from Role assignments only) WITH role_id_list AS ( SELECT string_agg(CAST("RoleId" AS varchar), ',') AS "RoleIdList" FROM "UserRole" INNER JOIN "User" AS "U" ON "U"."Id" = "UserRole"."UserId" WHERE "UserId" = @userId OR "U"."UserName" = @userId OR @userId IS NULL OR @userId = '0' ), role_id_array AS ( SELECT unnest(string_to_array("RoleIdList", ',')) AS "RoleId" FROM role_id_list WHERE "RoleIdList" IS NOT NULL )
SELECT U."UserId", RP."UiPermissionId" AS "PermissionId", P."PermissionValue", P."PermissionDisplayName", P."UiPermissionTypeId" AS "PermissionTypeId", A."DisplayName" AS "PermissionTypeName", P."PermissionParentId", UP."PermissionDisplayName" AS "PermissionParentName", P."ModuleId", AR."DisplayName" AS "ModuleName", P."IsActive" FROM "RoleUiPermission" RP INNER JOIN "UiPermission" AS P ON RP."UiPermissionId" = P."Id" AND P."IsActive" = TRUE INNER JOIN "AuthReferenceLookup" AS A ON A."Id" = P."UiPermissionTypeId" INNER JOIN "AuthReferenceLookup" AS AR ON AR."Id" = P."ModuleId" LEFT JOIN "UiPermission" AS UP ON UP."Id" = P."PermissionParentId" INNER JOIN "UserRole" AS U ON U."RoleId" = RP."RoleId" WHERE RP."RoleId" IN (SELECT "RoleId" FROM role_id_array) AND ( U."UserId" = (SELECT "Id" FROM "User" WHERE "Id" = @userId OR "UserName" = @userId LIMIT 1) OR @userId IS NULL OR @userId = '0' ) GROUP BY U."UserId", RP."UiPermissionId", P."PermissionValue", P."PermissionDisplayName", P."UiPermissionTypeId", A."DisplayName", P."PermissionParentId", UP."PermissionDisplayName", P."ModuleId", AR."DisplayName", P."IsActive";
-- 6. User Teams SELECT UT."TeamId" AS "Id", UT."MemberId", T."TeamName", T."TeamShortName", T."Description", T."TeamOwnerId", T."TeamCaptainId" FROM "TeamMember" AS UT INNER JOIN "Team" AS T ON T."Id" = UT."TeamId" INNER JOIN "User" AS U ON U."Id" = UT."MemberId" WHERE (T."IsDeleted" IS NULL OR T."IsDeleted" = FALSE) AND (UT."IsDeleted" IS NULL OR UT."IsDeleted" = FALSE) AND (U."IsDeleted" IS NULL OR U."IsDeleted" = FALSE) AND (UT."MemberId" = (SELECT "Id" FROM "User" WHERE "Id" = @userId OR "UserName" = @userId OR "oid" = @userId LIMIT 1) OR @userId IS NULL OR @userId = '0');


INSERT INTO "Permission"(
    "PermissionValue", "PermissionDisplayName", "PermissionSetId", "PermissionType", "ModuleId",
    "CreatedBy", "IsAuthorized", "OwnerId", "SysData", "TenantId", "SubTenantId",
    "IsDeleted", "IsActive", "CreatedDateTime"
)
VALUES (
    @PermissionValue, @PermissionDisplayName, @PermissionSetId, @PermissionType, @ModuleId,
    @CreatedBy, @IsAuthorized, @OwnerId, @SysData, @TenantId, @SubTenantId,
    FALSE, TRUE, NOW() AT TIME ZONE 'UTC'
)
RETURNING "Id";


-- Delete all permissions for the Role
DELETE FROM "RolePermission" WHERE "RoleId" = @RoleId;

-- If Permission exists
INSERT INTO "RolePermission"(
    "RoleId", "CreatedDateTime", "CreatedBy", "UpdatedDateTime", "UpdatedBy", "IsDeleted",
    "IsActive", "IsAuthorized", "OwnerId", "SysData", "TenantId", "SubTenantId", "PermissionId"
)
SELECT
    @RoleId, NOW() AT TIME ZONE 'UTC', @CreatedBy, NOW() AT TIME ZONE 'UTC', @CreatedBy,
    FALSE, TRUE, @IsAuthorized, @OwnerId, @SysData, @TenantId, @SubTenantId,
    UNNEST(STRING_TO_ARRAY(@PermissionIds, ','))::UUID AS "PermissionId"
WHERE @PermissionIds IS NOT NULL AND @PermissionIds <> '';


INSERT INTO "RoleUiPermission"(
    "RoleId", "UiPermissionId", "CreatedBy", "CreatedDateTime"
)
VALUES (
    @RoleId, @UiPermissionId, @CreatedBy, NOW() AT TIME ZONE 'UTC'
);


INSERT INTO "UiPermission"(
    "PermissionValue", "PermissionDisplayName", "UiPermissionTypeId", "PermissionParentId", "ModuleId", "CreatedBy",
    "IsAuthorized", "OwnerId", "SysData", "TenantId", "SubTenantId",
    "IsDeleted", "IsActive", "CreatedDateTime"
)
VALUES (
    @PermissionValue, @PermissionDisplayName, @PermissionTypeId, @PermissionParentId, @ModuleId, @CreatedBy,
    @IsAuthorized, @OwnerId, @SysData, @TenantId, @SubTenantId,
    FALSE, FALSE, NOW() AT TIME ZONE 'UTC'
)
RETURNING "Id";


INSERT INTO "UserRole"(
    "UserId", "CreatedDateTime", "CreatedBy", "UpdatedDateTime", "UpdatedBy", "IsDeleted",
    "IsActive", "IsAuthorized", "OwnerId", "SysData", "TenantId", "SubTenantId", "RoleId"
)
SELECT DISTINCT
    @UserId, NOW() AT TIME ZONE 'UTC', @CreatedBy, NOW() AT TIME ZONE 'UTC', @CreatedBy,
    FALSE, TRUE, @IsAuthorized, @OwnerId, @SysData, @TenantId, @SubTenantId,
    @RoleId
WHERE NOT EXISTS (SELECT 1 FROM "UserRole" WHERE "UserId" = @UserId AND "RoleId" = @RoleId);



DELETE FROM "UserRole" WHERE "UserId" = @UserId ;

INSERT INTO "UserRole"(
    "UserId", "CreatedDateTime", "CreatedBy", "UpdatedDateTime", "UpdatedBy", "IsDeleted",
    "IsActive", "IsAuthorized", "OwnerId", "SysData", "TenantId", "SubTenantId", "RoleId"
)
SELECT DISTINCT
    @UserId, NOW() AT TIME ZONE 'UTC', @CreatedBy, NOW() AT TIME ZONE 'UTC', @CreatedBy,
    FALSE, TRUE, @IsAuthorized, @OwnerId, @SysData, @TenantId, @SubTenantId,
    T."RoleId"
FROM (
    SELECT UNNEST(STRING_TO_ARRAY(@RoleIds, ',')) AS "RoleId"
    WHERE @RoleIds IS NOT NULL AND @RoleIds <> ''
    UNION ALL
    SELECT "Id" FROM "Role" WHERE "RoleName" = 'User'
) AS T;


-- NOTE: This query expects @Id1, @Id2, @Id3, @Id4 (for protected users)
-- and @PermissionIds (comma-separated string of UUIDs) to be resolved and passed by your C# application.
-- The conditional INSERT logic for protected users should also be managed in C#.

DELETE FROM "PermissionDenied" WHERE "UserId" = @UserId;

INSERT INTO "PermissionDenied"(
    "UserId", "CreatedDateTime", "CreatedBy", "UpdatedDateTime", "UpdatedBy", "IsDeleted",
    "IsActive", "IsAuthorized", "OwnerId", "SysData", "TenantId", "SubTenantId", "PermissionId"
)
SELECT DISTINCT
    @UserId, NOW() AT TIME ZONE 'UTC', @CreatedBy, NOW() AT TIME ZONE 'UTC', @CreatedBy,
    FALSE, TRUE, @IsAuthorized, @OwnerId, @SysData, @TenantId, @SubTenantId,
    UNNEST(STRING_TO_ARRAY(@PermissionIds, ','))::UUID AS "PermissionId"
WHERE @PermissionIds IS NOT NULL AND @PermissionIds <> '';



DELETE FROM "PermissionGranted" WHERE "UserId" = @UserId;

INSERT INTO "PermissionGranted"(
    "UserId", "CreatedDateTime", "CreatedBy", "UpdatedDateTime", "UpdatedBy", "IsDeleted",
    "IsActive", "IsAuthorized", "OwnerId", "SysData", "TenantId", "SubTenantId", "PermissionId"
)
SELECT DISTINCT
    @UserId, NOW() AT TIME ZONE 'UTC', @CreatedBy, NOW() AT TIME ZONE 'UTC', @CreatedBy,
    FALSE, TRUE, @IsAuthorized, @OwnerId, @SysData, @TenantId, @SubTenantId,
    UNNEST(STRING_TO_ARRAY(@PermissionIds, ','))::UUID AS "PermissionId"
WHERE UNNEST(STRING_TO_ARRAY(@PermissionIds, ',')) IS NOT NULL;



        INSERT INTO "User" (
            "Id", "UserName", auth_type, "EmpId", "EmpType", "mobile", "Email", "Position", "BusinessUnit", "oid",
            given_name, family_name, preferred_username, "FirstName", "LastName", "SecondaryEmail",
            "PhoneNumber", "Extension", display_name, "ManagerId", "Designation", "Department",
            "Location", "Organization", "CreatedDateTime", "UpdatedDateTime", "IsDeleted",
            "IsActive", "IsAuthorized", "OwnerId", "CreatedBy", "UpdatedBy", "SysData",
            "TenantId", "SubTenantId", "AccessLevel"
        )
        VALUES (
            @Id, @UserName, @auth_type, @EmpId, @EmpType, @mobile, @Email, @Position, @BusinessUnit, @OID,
            @given_name, @family_name, @preferred_username, @FirstName, @LastName, @SecondaryEmail,
            @PhoneNumber, @Extension, @display_name, @ManagerId, @Designation, @Department,
            @Location, @Organization,
            NOW() AT TIME ZONE 'UTC',
            NOW() AT TIME ZONE 'UTC',
            FALSE, TRUE, @IsAuthorized, @OwnerId,
            @CreatedBy, @CreatedBy, @SysData,
            @TenantId, @SubTenantId , @AccessLevel
        )
        RETURNING "Id";

        INSERT INTO "UserRole"("UserId", "RoleId")
        SELECT @Id, "Id" FROM "Role" WHERE "RoleName" = 'User';

		INSERT INTO "UserPasswordHash"
(
    "UserId",
    "PasswordHash",
    "UpdatedBy",
    "UpdatedDateTime"
)
VALUES
(
    @Id,
    @PasswordHash,
    @CreatedBy,
    NOW() AT TIME ZONE 'UTC'
);

-- NOTE: This query contains two UPDATE statements. -- For Dapper, you can execute them as a single command string. -- Ensure your C# application manages transactions if both updates need to be atomic.
UPDATE "User" SET "PhoneNumber" = @PhoneNumber, "Extension" = @Extension, "Email" = @Email, "AccessLevel" = @AccessLevel, "UpdatedBy" = @UpdatedBy, "UpdatedDateTime" = @UpdatedDateTime WHERE "Id" = @Id;
UPDATE "UserRole" SET "RoleId" = @UserRoleId, "UpdatedBy" = @UpdatedBy, "UpdatedDateTime" = @UpdatedDateTime WHERE "UserId" = @Id;


INSERT INTO "UserProfile" (
    "UserId", "DateOfJoining", "PrimarySkills", "SecondarySkills", "TertiarySkills", "OtherSkills"
)
VALUES (
    @UserId, @DateOfJoining, @PrimarySkills, @SecondarySkills, @TertiarySkills, @OtherSkills
);


INSERT INTO "UserActivity" (
    "UserId",
    "LastLoginDateTime",
    "LastLogoutDateTime",
    "LastActivityDateTime",
    "LastActivityModule",
    "LastActionType",
    "LastActivityDetail",
    "CreatedBy",
    "CreatedDateTime"
)
VALUES (
    @UserId,
    @LastLoginDateTime,
    @LastLogoutDateTime,
    @LastActivityDateTime,
    @LastActivityModule,
    @LastActionType,
    @LastActivityDetail,
    @CreatedBy,
    @CreatedDateTime
)
RETURNING "Id"


INSERT INTO "Team"(
    "TeamName", "TeamShortName", "Description", "TeamOwnerId", "TeamCaptainId",
    "CreatedBy", "CreatedDateTime", "IsDeleted", "IsActive"
)
VALUES(
    @TeamName, @TeamShortName, @Description, @TeamOwnerId, @TeamCaptainId,
    @CreatedBy, NOW() AT TIME ZONE 'UTC', FALSE, TRUE
)
RETURNING "Id";


INSERT INTO "TeamMember"("MemberId", "TeamId", "CreatedBy", "CreatedDateTime", "IsDeleted")
SELECT
    UNNEST(STRING_TO_ARRAY(@MemberIds, ','))::UUID AS "MemberId",
    @TeamId::UUID AS "TeamId",
    @CreatedBy,
    NOW() AT TIME ZONE 'UTC',
    FALSE
WHERE @MemberIds IS NOT NULL AND @MemberIds <> '';
